def mru_cache(maxsize=128, typed=False):
    """decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def mru_callable(cache):
        def _mru_get(k):
            try:
                return cache[k]
            except KeyError:
                pass # key not found
            cache[k] = []
            return cache[k]
        def _mru_evict(k, value):
            try:
                del cache[k]
            except KeyError:
                pass # key not found
            cache[k] = value
        return _mru_get, _mru_evict
    def decorator(fn):
        _, evict = mru_callable(cache={})
        def wrapper(*args, **kwargs):
            k = fn._cached_key(*args, **kwargs)
            v = fn._cached_get(k)
            if v is None:
                v = fn(*args, **kwargs)
                evict(k, v)
            return v
        wrapper._cached_key = fn
        wrapper._cached_get = mru_callable(maxsize)[0]
        return wrapper
    return decorator

