def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    # Apply defaults to the observer schema of the application manifest.
    # Note: This method mutates the app manifest.
    app.spec.manifest["metadata"]["observer"] = {}

    # Add a default observer schema for each resource present in the manifest.
    for resource in app.spec.manifest:
        if resource not in app.spec.observer_schema:
            # Create a new observer schema for the resource.
            app.spec.observer_schema[resource] = {}

            # Add a default observer schema for each spec field.
            for field in app.spec.manifest[resource]["spec"]:
                app.spec.observer_schema[resource][field] = {
                    "type": "unknown",
                    "default": None,
                    "required": False,
                }

