def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    *sql* (str or bytes) is the SQL query.

    *params* (dict or list) contains the set of in-style parameters. It maps each parameter (str or int) to value. If .SQLParams.in_style is a named parameter style, then params must be a dict. If .SQLParams.in_style is an ordinal parameter style, then params must be a list.

    Returns a tuple containing:

    - The formatted SQL query (str or bytes).

    - The set of converted out-style parameters (dict or list).
    """
    # Convert the in-style parameters to out-style parameters
    out_params = {}
    if isinstance(params, dict):
        # Named parameter style
        for key in params:
            out_params[key] = params[key]
    else:
        # Ordinal parameter style
        for i, param in enumerate(params):
            out_params[i] = param

    # Replace the in-style parameters with out-style parameters in the SQL query
    for in_style_param, out_style_param in self.in_style_map.items():
        sql = sql.replace(in_style_param, out_style_param % out_params)

    return sql, out_params

