def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Or) and isinstance(arg.args[0], And):
            # Absorption
            if arg.args[0].args[0] == arg.args[1]:
                new_args.append(arg.args[0].args[0])
            else:
                new_args.append(And(arg.args[0].args[0], arg.args[1]))
        elif isinstance(arg, And) and isinstance(arg.args[0], Not) and isinstance(arg.args[1], Or):
            # Negative absorption
            if arg.args[0].args[0] == arg.args[1].args[1]:
                new_args.append(And(arg.args[0].args[0], arg.args[1].args[0]))
            elif arg.args[0].args[0] == arg.args[1].args[0]:
                new_args.append(Or(arg.args[0].args[0], arg.args[1].args[1]))
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

