    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        base_re = re.compile(
            r'''((?:(?:\\['"])|(?:\\\\)|(?:\\)|[^\s'"\\])+|\s+)+|'[^']*'|"[^"]*"''')
    else:
        base_re = re.compile(
            r'''((?:(?:\\['"])|(?:\\\\)|(?:\\)|[^\s'"\\])+|\s+)+|"[^"]*"''')

    def _split(m):
        return base_re.split(m.group(0))

    return base_re.split(s, 1, _split)

