def _include_groups(parser, groups, exclude=None):
    """
    Resolves the include dict directive in the spec files.

    :param parser:
    :param groups:
    :param exclude:
    :return:
    """
    resolved_groups = {}
    for key, path in groups.items():
        if exclude and key in exclude:
            continue
        try:
            resolved_groups[key] = parser.resolve(path)
        except KeyError:
            pass
    return resolved_groups

